from taf.gnb.oam.coam.cu import cu

from .bts import Bts


class BtsCloudCu(Bts):
    """ Represents API to CU part of gNB BTS with Cloud topology. """

    def __init__(self):
        super(BtsCloudCu, self).__init__()
        self._api = cu()

    def _connect_to(self, config, name, log_dir, timeout, **kwargs):
        if config and config.cu.oam_http_connection_details:
            self._host = config.cu.oam_http_connection_details.addr
            bts_port = config.cu.oam_http_connection_details.port
            username = config.cu.oam_http_connection_details.username
            password = config.cu.oam_http_connection_details.password
        else:
            self._host = '192.168.100.129'
            bts_port = 443
            username = 'Nemuadmin'
            password = 'nemuuser'

        self._logger.info(self._CONNECTION_LOG_MSG.format('gNB Cloud CU', self._host, bts_port, username, password))

        self._api.connect_to(host=self._host,
                             port=bts_port,
                             username=username,
                             password=password,
                             secure=True,
                             alias=name,
                             timeout=timeout)

    def _get_active_alarms(self, connection, timeout):
        return self._api.get_active_alarms(connection=connection, timeout=timeout)['alarms']

    def _disconnect(self, connection):
        self._api.disconnect(connection=connection)
